arrayPipelines.data:
[
  {
    "$match": {
      "$expr": {
        "$and": [
          {
            "$gte": [
              {
                "$cond": {
                  "if": { "$gt": ["$timestamp", 9999999999] },
                  "then": "$timestamp",
                  "else": { "$multiply": ["$timestamp", 1000] }
                }
              },
              {{ start_date.selectedDate ? new Date(start_date.selectedDate).getTime() : 0 }}
            ]
          },
          {
            "$lte": [
              {
                "$cond": {
                  "if": { "$gt": ["$timestamp", 9999999999] },
                  "then": "$timestamp",
                  "else": { "$multiply": ["$timestamp", 1000] }
                }
              },
              {{ end_date.selectedDate ? new Date(end_date.selectedDate).getTime() : 4102444800000 }}
            ]
          }
        ]
      },
      "email": {{ user_id.selectedOptionValue ? user_id.selectedOptionValue : { "$exists": true } }},
      "environment": {{ env_select.selectedOptionValue ? env_select.selectedOptionValue : { "$exists": true } }},
      "client_id": {{ client_id.selectedOptionValue ? client_id.selectedOptionValue : { "$exists": true } }}
    }
  },
  { "$sort": { "timestamp": -1 } },
  {
    "$project": {
      "_id": 0,
      "Email Date": {
        "$cond": {
          "if": {
            "$and": [
              { "$ne": ["$email_date", null] },
              { "$gt": ["$email_date", 0] }
            ]
          },
          "then": {
            "$dateToString": {
              "format": "%Y-%m-%d",
              "date": {
                "$toDate": {
                  "$cond": {
                    "if": { "$gt": ["$email_date", 9999999999] },
                    "then": "$email_date",
                    "else": { "$multiply": ["$email_date", 1000] }
                  }
                }
              }
            }
          },
          "else": "N/A"
        }
      },
      "Event Date": {
        "$cond": {
          "if": {
            "$and": [
              { "$ne": ["$timestamp", null] },
              { "$gt": ["$timestamp", 0] }
            ]
          },
          "then": {
            "$dateToString": {
              "format": "%Y-%m-%d %H:%M:%S",
              "date": {
                "$toDate": {
                  "$cond": {
                    "if": { "$gt": ["$timestamp", 9999999999] },
                    "then": "$timestamp",
                    "else": { "$multiply": ["$timestamp", 1000] }
                  }
                }
              }
            }
          },
          "else": "N/A"
        }
      },
      "Event ID": { "$ifNull": ["$sg_event_id", "N/A"] },
      "Event Type": { "$ifNull": ["$event", "N/A"] },
      "Client ID": { "$ifNull": ["$client_id", "N/A"] },
      "Environment": { "$ifNull": ["$environment", "N/A"] },
      "Recipient Email": { "$ifNull": ["$email", "N/A"] },
      "Click URL": { "$ifNull": ["$url", ""] },
      "Workflow Name": { "$ifNull": ["$workflow_name", "N/A"] },
      "Workflow ID": { "$ifNull": ["$workflow_id", "N/A"] },
      "Subject": { "$ifNull": ["$subject", "N/A"] },
      "Template Name": { "$ifNull": ["$template_name", "N/A"] },
      "Message ID": { "$ifNull": ["$sg_message_id", "N/A"] },
      "Origin": { "$ifNull": ["$event_origin", "N/A"] }
    }
  }
]

query.data:
[
	{
		"$match": {
			"timestamp": {
				"$gte": {{ Math.floor(new Date(start_date.selectedDate).getTime()) }},
				"$lte": {{ Math.floor(new Date(end_date.selectedDate).getTime()) }}
			},
			"email": {{ user_id.selectedOptionValue || {"$exists": true} }},
			"environment": {{ env_select.selectedOptionValue || {"$exists": true} }}
		}
	},
	{ "$sort": { "timestamp": -1 } },
	{ "$skip": {{ (Table1.pageNo - 1) * 50 }} },
	 { "$limit": 50 },
	{
		"$project": {
			"_id": 0,
			"Email Date": {
				"$cond": {
					"if": { "$gt": ["$email_date", 0] },
					"then": {
						"$dateToString": {
							"format": "%Y-%m-%d",
							"date": { "$toDate": { "$multiply": ["$email_date", 1] } }
						}
					},
					"else": "N/A"
				}
			},
			"Event Date": {
				"$dateToString": {
					"format": "%Y-%m-%d %H:%M:%S",
					"date": { "$toDate": { "$multiply": ["$timestamp", 1000] } }
				}
			},
			"Event ID": { "$ifNull": ["$sg_event_id", "N/A"] },
			"Event Type": { "$ifNull": ["$event", "N/A"] },
			"Client ID": { "$ifNull": ["$client_id", "N/A"] },
			"Environment": { "$ifNull": ["$environment", "N/A"] },
			"Recipient Email": { "$ifNull": ["$email", "N/A"] },
			"Click URL": { "$ifNull": ["$url", ""] },
			"Workflow Name": { "$ifNull": ["$workflow_name", "N/A"] },
			"Workflow ID": { "$ifNull": ["$workflow_id", "N/A"] },
			"Subject": { "$ifNull": ["$subject", "N/A"] },
			"Template Name": { "$ifNull": ["$template_name", "N/A"] },
			"Message ID": { "$ifNull": ["$sg_message_id", "N/A"] }
		}
	}
]

